let chatInput = $json.chatInput || $input.first().json.body?.chatInput;
let sessionId = $json.sessionId || $input.first().json.body?.sessionId;

return [{ json: { chatInput, sessionId } }];

try {
  const programResp = await $http.request({ method: 'GET', url: 'http://localhost:5555/api/program', returnFullResponse: true });
  let body = programResp.body;
  if (typeof body === 'string') { try { body = JSON.parse(body); } catch { return JSON.stringify({ error: 'invalid program response', raw: body }); } }
  if (!body || typeof body !== 'object') return JSON.stringify({ error: 'invalid program response shape' });

  const code = body.programCode || body.source || '';
  const sourceLines = Number(body.sourceLines) || 0;
  const hasParseError = body.hasParseError === true;
  const parseErrorMessage = body.parseErrorMessage || null;
  const isExecutable = body.isExecutable === true || (sourceLines > 0 && !hasParseError && !!code);

  if (!code || sourceLines === 0) {
    return JSON.stringify({ error: 'no_program_loaded', message: 'Kein Programm in der Steuerung geladen.' });
  }
  if (hasParseError) {
    return JSON.stringify({ error: 'parse_error', message: parseErrorMessage || 'Programm hat Parse-Fehler', code, sourceLines });
  }

  // Labels separat holen
  let inputLabels = {};
  let outputLabels = {};
  try {
    const lblResp = await $http.request({ method: 'GET', url: 'http://localhost:5555/api/labels', returnFullResponse: true });
    let lblBody = lblResp.body;
    if (typeof lblBody === 'string') { try { lblBody = JSON.parse(lblBody); } catch { lblBody = null; } }
    if (lblBody && typeof lblBody === 'object') {
      inputLabels = lblBody.inputs || lblBody.inputLabels || {};
      outputLabels = lblBody.outputs || lblBody.outputLabels || {};
    }
  } catch (e) { /* labels optional, ignore */ }

  return JSON.stringify({
    code,
    sourceLines,
    hasParseError,
    isExecutable,
    inputLabels,
    outputLabels
  });
} catch (e) {
  return JSON.stringify({ error: 'controller_unreachable', message: e.message });
}
